// Generated by `just generate` from `src/plugins/claudetto/slices/guard/lab/print.test.ts`. Edit the source and run `just generate`.
// Lab tests of the `tool.call` hook on `Bash` of the `guard` slice: the deny of a command that only prints a file (design D22).
// The hook sits above the stub of the engine, and the stub of the file system gives the line count.
// No command runs.

import type { On } from "claude-code";
import { type Engine, expect, test } from "claude-code/testing";

/** Stubs the engine answer, the session, and the file system: each path of `texts` is a file with that text. */
const project = (on: On, texts: Record<string, string> = {}): string[] => {
  const seen: string[] = [];
  // On Windows the engine can give a path with `\` and a drive letter, so the key drops both.
  const key = (p: string) => {
    seen.push(p);
    return p.replace(/\\/g, "/").replace(/^[A-Za-z]:/, "");
  };
  on("tool.call", () => ({ result: "ok" }));
  on("session.cwd", () => ({ value: "/p" }));
  on("fs.exists", (_$, e) => ({ value: key(e.path) in texts }));
  on("fs.stat", (_$, e) => ({
    value: {
      kind: "file" as const,
      size: (texts[key(e.path)] ?? "").length,
      mtimeMs: 0,
      isLink: false,
    },
  }));
  on("fs.read", (_$, e) => ({ value: texts[key(e.path)] ?? "" }));
  return seen;
};

const call = ($: Engine, command: string) =>
  $.tool.call({ tool: "Bash", command });

test("a `Bash` print of a file is denied with the `Read` range", async ($: Engine, on: On) => {
  const seen = project(on, { "/p/big.txt": "line\n".repeat(2000) });
  const out = await call($, "sed -n '40,80p' big.txt");
  const deny = "deny" in out ? out.deny : undefined;
  expect(typeof deny, `fs paths: ${seen.join(", ")}`).toBe("string");
  expect(deny).toContain("`offset` 40");
  expect(deny).toContain("`limit` 41");
});

test("a `tail` print names the last lines from the line count", async ($: Engine, on: On) => {
  project(on, { "/p/big.txt": "line\n".repeat(100) });
  const out = await call($, "tail -n 20 big.txt");
  const deny = "deny" in out ? out.deny : undefined;
  expect(deny).toContain("`offset` 81");
  expect(deny).toContain("`limit` 20");
});

// biome-ignore lint/plugin: a test name that a `slice.ts` file references
test("a compound command is denied when each part only prints a file, and not when another part does work", async ($: Engine, on: On) => {
  project(on, { "/p/big.txt": "line\n".repeat(10) });
  expect("deny" in (await call($, "cat /p/big.txt && cat /p/big.txt"))).toBe(
    true,
  );
  expect("deny" in (await call($, "ls && cat /p/big.txt"))).toBe(false);
});

// biome-ignore lint/plugin: a test name that a `slice.ts` file references
test("a print of a file that is absent, a generated file, and a command that does not print stay allowed", async ($: Engine, on: On) => {
  project(on, { "/p/run.log": "line\n", "/p/a.txt": "line\n" });
  for (const command of [
    "cat missing.txt",
    "cat run.log",
    "cat a.txt | grep line",
    "ls /p",
  ])
    expect("deny" in (await call($, command)), command).toBe(false);
});
